  const sup = beta => { const b = beta * D2R, u = [0, Math.sin(b), -Math.cos(b)]; return { root: madd(ank, u, .93), pel: [-(90 - beta), 0, 0], lum: [0, 0, 0], tho: [0, 0, 0], neck: 4, ...symLegs({ el: 0, az: 3, bend: 2 }) }; };
