  const flare = p => { p = clone(p); if (p.aL && p.aL.t) { const w = p.aL.f === 'w'; p.aL.pole = w ? [1, -.1, 0] : [1, .15, -.1]; p.aR.pole = w ? [-1, -.1, 0] : [-1, .15, -.1]; } return p; };
  const sag = p => ({ ...clone(p), root: v3(p.root, 1, -.07), lum: v3(p.lum, 0, -16) });
